/* تبديل الوضع الداكن/الفاتح */
const applyTh=t=>{document.documentElement.dataset.theme=t;const b=$('.theme');if(b)b.textContent=t==='light'?'🌙':'☀️'};
let saved=null;try{saved=localStorage.getItem('nobles_theme')}catch(e){}
applyTh(saved==='light'?'light':'dark');
const thBtn=$('.theme');if(thBtn)thBtn.onclick=()=>{const t=document.documentElement.dataset.theme==='light'?'dark':'light';try{localStorage.setItem('nobles_theme',t)}catch(e){}applyTh(t)};
