const own=el=>[...el.childNodes].find(n=>n.nodeType===3&&n.nodeValue.trim());
const gt=el=>el.children.length?(own(el)?.nodeValue??''):el.textContent;
const ED=(()=>{const c={},o=[];$$('body *').forEach(el=>{if(el.closest('script,style,select,option,[data-programs],#art,#artlist,.toast,.pre,.nav,[data-count]')||!own(el)||[...el.children].some(x=>!/^(IMG|BR)$/.test(x.tagName)))return;const p=el.closest('.foot')?'g':el.closest('.page')?.id.slice(2)||document.body.dataset.page||'x';c[p]=(c[p]||0)+1;o.push([p+':'+c[p],el])});return o})();
const DT={};ED.forEach(([k,el])=>{const n=own(el);DT[k]=n.nodeValue;if(CFG.t&&CFG.t[k]!=null)n.nodeValue=CFG.t[k]});
$$('img[data-n]').forEach(i=>{const u=CFG.im&&CFG.im[i.dataset.n];if(u)i.src=u});
document.addEventListener('load',e=>{if(e.target.tagName==='IMG')e.target.style.display=''},true);
if(CFG.st)$$('[data-count]').forEach((e,i)=>CFG.st[i]&&(e.dataset.count=CFG.st[i]));

let D=cl(CFG),dirty=false,tab='g',tm;
const flush=()=>{clearTimeout(tm);try{localStorage.setItem('nobles_cfg',JSON.stringify(D))}catch(e){toast('تعذر الحفظ: مساحة المتصفح ممتلئة أو غير متاحة')}};
const sv=()=>{clearTimeout(tm);tm=setTimeout(flush,350);dirty=true};
const setp=(p,v)=>{const k=p.split('.');let o=D;k.slice(0,-1).forEach((s,i)=>{o[s]??=/^\d+$/.test(k[i+1])?[]:{};o=o[s]});o[k[k.length-1]]=v};
const rw=(l,p,v,t)=>`<label>${l}</label>${t?`<textarea data-b="${p}" rows="3">${esc(v)}</textarea>`:`<input data-b="${p}" value="${esc(v)}">`}`;
const CATS=[['prog','برمجة'],['ai','ذكاء اصطناعي'],['design','تصميم مواقع'],['robot','روبوتات']];
const pn=i=>i<6?i+3:30+i;
const T={
g:()=>`<div class="af">${rw('البريد الإلكتروني الذي تصله طلبات التسجيل والشراكة','email',D.email||'')}${rw('رابط الخريطة','map',D.map||MAP)}${['عدد الطلاب','عدد البرامج','عدد المدربين'].map((l,i)=>rw(l+' (الإحصائيات)','st.'+i,D.st&&D.st[i]!=null?D.st[i]:[500,6,20][i])).join('')}</div>`,
p:()=>{D.P??=cl(P0);return D.P.map((p,i)=>`<div class="it"><b>${i+1}. ${esc(p.t)}</b><div class="pv" style="height:150px;margin-top:8px">${D.im&&D.im[pn(i)]?`<img src="${D.im[pn(i)]}" alt="">`:'لا توجد صورة'}</div><label class="btn out">رفع صورة البرنامج<input type="file" accept="image/*" data-up="${pn(i)}" hidden></label><div class="af">${rw('العنوان',`P.${i}.t`,p.t)}${rw('الوصف',`P.${i}.d`,p.d,1)}${rw('المستوى',`P.${i}.lv`,p.lv)}${rw('المدة',`P.${i}.du`,p.du)}<label>التصنيف</label><select data-b="P.${i}.cat">${CATS.map(([v,n])=>`<option value="${v}" ${p.cat===v?'selected':''}>${n}</option>`).join('')}</select></div><button class="btn out" data-del="P.${i}">حذف</button></div>`).join('')+'<button class="btn pri" data-add="P">+ إضافة برنامج</button>'},
a:()=>{D.A??=cl(A0);return D.A.map((a,i)=>`<div class="it"><b>${esc(a.t)}</b><div class="pv" style="height:150px;margin-top:8px">${D.im&&D.im[15+i]?`<img src="${D.im[15+i]}" alt="">`:'لا توجد صورة'}</div><label class="btn out">رفع صورة المقال<input type="file" accept="image/*" data-up="${15+i}" hidden></label><div class="af">${rw('العنوان',`A.${i}.t`,a.t)}${rw('التاريخ (YYYY-MM-DD) — الأحدث يظهر كمقال رئيسي',`A.${i}.d`,a.d)}<label>النص (كل سطر جديد = فقرة)</label><textarea data-b="A.${i}.x" data-ar rows="6">${esc(a.x.join('\n\n'))}</textarea></div><button class="btn out" data-del="A.${i}">حذف</button></div>`).join('')+'<button class="btn pri" data-add="A">+ إضافة مقال</button>'},
pt:()=>{D.PT??=cl(PT0);return D.PT.map((p,i)=>`<div class="it"><b>${esc(p.t)}</b><div class="pv" style="height:120px;margin-top:8px">${p.img?`<img src="${p.img}" alt="">`:'لا توجد صورة'}</div><label class="btn out">رفع شعار الشريك<input type="file" accept="image/*" data-upc="PT.${i}.img" hidden></label><div class="af">${rw('اسم الشريك',`PT.${i}.t`,p.t)}</div><button class="btn out" data-del="PT.${i}">حذف</button></div>`).join('')+'<button class="btn pri" data-add="PT">+ إضافة شريك</button>'},
i:()=>{const S=[[1,'اللوجو'],[2,'صورة "عن الأكاديمية"'],...(D.P||P0).map((p,k)=>[pn(k),'برنامج: '+p.t]),...[9,10,11,12,13,14].map(n=>[n,'شريك '+(n-8)]),...(D.A||A0).map((a,k)=>[15+k,'مقال: '+a.t])];
 return `<p class="hint">تُضغط الصورة تلقائيًا وتُحفظ في المتصفح. للنشر استخدم تصدير content.js من تبويب الأمان والنسخ.</p><div class="gal">${S.map(([n,l])=>{const m=D.im&&D.im[n];return `<div class="it"><div class="pv">${m?`<img src="${m}" alt="">`:'لا توجد صورة'}</div><small>${esc(l)}</small><div class="cta" style="margin-top:8px"><label class="btn out">رفع<input type="file" accept="image/*" data-up="${n}" hidden></label>${m?`<button class="btn out" data-rm="${n}">إزالة</button>`:''}</div></div>`}).join('')}</div>`},
t:()=>`<div class="it"><p>لتعديل أي نص في أي صفحة (عناوين، فقرات، أزرار، الفوتر): اضغط الزر، ثم اضغط على النص مباشرة في الصفحة واكتب، ثم اضغط «حفظ» في الشريط السفلي. يمكنك التنقل بين الصفحات أثناء التحرير.</p><button class="btn pri" data-act="edit" style="margin-top:12px">تفعيل وضع تحرير النصوص</button></div>`,
s:()=>`<div class="it"><b>النشر المباشر على السيرفر</b><p class="hint" style="text-align:right">أي تعديل تحفظه بزر «حفظ التعديلات» أو «حفظ وإغلاق» يُرسل تلقائيًا إلى save.php على السيرفر ليستبدل content.js ويظهر لكل الزوار فورًا. لازم يكون save.php مرفوعًا في جذر الموقع وكلمة سره مطابقة لنفس القيمة في الكود. لو فشل النشر (مشكلة استضافة أو صلاحيات)، تفضل التعديلات محفوظة في متصفحك فقط وتقدر تعيد المحاولة من هنا، أو تستخدم تصدير content.js يدويًا كحل احتياطي.</p><div class="af"><button class="btn pri" data-act="publish">📡 إعادة محاولة النشر الآن</button></div></div>
<div class="it"><b>تغيير كلمة السر</b><div class="af"><input id="npw" type="password" placeholder="كلمة السر الجديدة (6 أحرف على الأقل)"><button class="btn pri" data-act="pw">حفظ كلمة السر</button></div></div>
<div class="it"><b>نسخة احتياطية يدوية (اختياري)</b><p class="hint" style="text-align:right">تنزيل نسخة من content.js كبديل احتياطي لو احتجت ترفعها يدويًا بنفسك.</p><div class="af"><button class="btn out" data-act="export">تجهيز content.js</button><textarea id="exp" rows="5" readonly hidden></textarea></div></div>
<div class="it"><b>استيراد / إعادة ضبط</b><div class="af"><textarea id="imp" rows="4" placeholder="الصق محتوى content.js هنا"></textarea><button class="btn out" data-act="import">استيراد</button><button class="btn out" data-act="reset">حذف كل التعديلات والعودة للأصل</button></div></div>`};
const TABS=[['g','عام'],['p','البرامج'],['a','المقالات'],['pt','الشركاء'],['i','الصور'],['t','النصوص'],['s','الأمان والنسخ']];
const adm=document.createElement('div');adm.className='adm';adm.hidden=true;
const draw=()=>{const y=adm.scrollTop;adm.innerHTML=`<div class="wrap"><div class="top"><h2 class="gold">لوحة التحكم</h2><div class="cta"><button class="btn pri" data-act="save">💾 حفظ التعديلات</button><button class="btn out" data-act="close">حفظ وإغلاق</button></div></div><div class="tabs">${TABS.map(([k,n])=>`<button data-tab="${k}" class="${k===tab?'on':''}">${n}</button>`).join('')}</div>${T[tab]()}</div>`;adm.scrollTop=y};
const bar=document.createElement('div');bar.className='edbar';bar.hidden=true;bar.innerHTML='<span>وضع تحرير النصوص</span><button class="btn pri" data-s>حفظ</button><button class="btn out" data-c>إلغاء</button>';
const lg=document.createElement('div');lg.className='lgm';lg.hidden=true;lg.innerHTML='<form><h3 class="gold">دخول الإدارة</h3><input type="password" id="pw" placeholder="كلمة السر" autocomplete="off"><div class="err" id="perr"></div><button class="btn pri" type="submit">دخول</button><button class="btn out" type="button" id="pcx">إلغاء</button></form>';
document.body.append(lg,adm,bar);
const sure=b=>{if(b.dataset.s)return true;b.dataset.o=b.textContent;b.dataset.s=1;b.textContent='اضغط مرة أخرى للتأكيد';setTimeout(()=>{delete b.dataset.s;b.textContent=b.dataset.o},3000);return false};
const up=(n,f)=>{if(!f)return;const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const s=Math.min(1,1000/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*s;c.height=im.height*s;c.getContext('2d').drawImage(im,0,0,c.width,c.height);(D.im??={})[n]=c.toDataURL('image/jpeg',.85);sv();draw()};im.src=r.result};r.readAsDataURL(f)};
const upc=(p,f)=>{if(!f)return;const r=new FileReader();r.onload=()=>{const im=new Image();im.onload=()=>{const s=Math.min(1,1000/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*s;c.height=im.height*s;c.getContext('2d').drawImage(im,0,0,c.width,c.height);setp(p,c.toDataURL('image/jpeg',.85));sv();draw()};im.src=r.result};r.readAsDataURL(f)};
adm.addEventListener('input',e=>{const t=e.target,p=t.dataset.b;if(!p)return;setp(p,t.hasAttribute('data-ar')?t.value.split(/\n+/).filter(Boolean):t.value);sv()});
adm.addEventListener('change',e=>{const t=e.target;if(t.dataset.up)up(t.dataset.up,t.files[0]);if(t.dataset.upc)upc(t.dataset.upc,t.files[0])});
adm.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.tab){tab=b.dataset.tab;return draw()}
 if(b.dataset.add){const k=b.dataset.add;if(k==='P'){D.P??=cl(P0);D.P.push({id:'c'+Date.now(),cat:'prog',ic:'📘',t:'برنامج جديد',d:'وصف مختصر للبرنامج',lv:'مبتدئ',du:'8 أسابيع'})}else if(k==='PT'){D.PT??=cl(PT0);D.PT.push({t:'شريك جديد',img:''})}else{D.A??=cl(A0);D.A.push({t:'مقال جديد',d:new Date().toISOString().slice(0,10),x:['نص المقال']})}sv();return draw()}
 if(b.dataset.del){if(!sure(b))return;const[k,i]=b.dataset.del.split('.');D[k].splice(+i,1);sv();return draw()}
 if(b.dataset.rm){delete D.im[b.dataset.rm];sv();return draw()}
 const a=b.dataset.act;
 if(a==='save'){flush();await publish()}
 if(a==='close'){flush();await publish();adm.hidden=true;if(dirty)location.reload()}
 if(a==='publish'){await publish()}
 if(a==='edit'){flush();adm.hidden=true;document.body.classList.add('ed');ED.forEach(([,el])=>el.contentEditable='true');$$('.rv').forEach(x=>x.classList.add('in'));bar.hidden=false;toast('اضغط على أي نص لتعديله')}
 if(a==='pw'){const v=$('#npw').value;if(v.length<6)return toast('كلمة السر قصيرة');D.pw=hs(v);sv();flush();await publish();$('#npw').value=''}
 if(a==='export'){const t=`window.SITE_CFG=${JSON.stringify(D)};`,x=$('#exp');x.value=t;x.hidden=false;x.select();try{const l=document.createElement('a');l.href=URL.createObjectURL(new Blob([t],{type:'text/javascript'}));l.download='content.js';l.click()}catch(er){}}
 if(a==='import'){try{const s=$('#imp').value;D=JSON.parse(s.slice(s.indexOf('{'),s.lastIndexOf('}')+1));sv();flush();draw();toast('تم الاستيراد')}catch(er){toast('المحتوى غير صالح')}}
 if(a==='reset'){if(!sure(b))return;try{localStorage.removeItem('nobles_cfg')}catch(er){}location.reload()}});
bar.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-c'))return location.reload();
 if(b.hasAttribute('data-s')){D.t??={};ED.forEach(([k,el])=>{const v=gt(el);v!==DT[k]?D.t[k]=v:delete D.t[k]});flush();await publish();location.reload()}});
document.addEventListener('click',e=>{if(document.body.classList.contains('ed')&&e.target.closest('[contenteditable]'))e.preventDefault()},true);
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&document.body.classList.contains('ed')&&e.target.isContentEditable)e.preventDefault()});
lg.querySelector('form').onsubmit=e=>{e.preventDefault();const i=$('#pw');if(hs(i.value)===(D.pw||DEF_PW)){lg.hidden=true;i.value='';$('#perr').textContent='';tab='g';adm.hidden=false;draw()}else $('#perr').textContent='كلمة السر غير صحيحة'};
$('#pcx').onclick=()=>{lg.hidden=true};
let ck=0,ct;const cp=$('.copy');cp&&cp.addEventListener('click',()=>{if(document.body.classList.contains('ed'))return;ck++;clearTimeout(ct);ct=setTimeout(()=>ck=0,2000);if(ck>=5){ck=0;lg.hidden=false;$('#pw').focus()}});
/* مقالات: تبديل تلقائي كل 3 ثواني + زر عرض الكل */
(()=>{const art=$('#art');if(!art)return;
 const fold=()=>{if(art.querySelector('.more'))return;const ps=[...art.querySelectorAll(':scope > p')];if(ps.length<2)return;ps.slice(1).forEach(p=>p.hidden=true);const b=document.createElement('button');b.className='btn out more';b.textContent='عرض الكل';b.style.marginTop='14px';b.onclick=()=>{const open=b.dataset.o==='1';ps.slice(1).forEach(p=>p.hidden=open);b.dataset.o=open?'':'1';b.textContent=open?'عرض الكل':'إخفاء'};art.appendChild(b)};
 new MutationObserver(fold).observe(art,{childList:true});fold();
})();
/* نموذج التسجيل: مخفي، ويظهر بس عند الضغط على سجّل الآن أو تواصل معانا */
(()=>{const reg=$('#register');if(!reg)return;
 const show=()=>{reg.hidden=false};
 const apply=()=>{const want=location.hash==='#register'||new URLSearchParams(location.search).get('course');
  if(want){show();setTimeout(()=>reg.scrollIntoView({behavior:'smooth'}),50)}else reg.hidden=true};
 document.querySelectorAll('a[href="#register"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();show();history.replaceState(null,'','#register');reg.scrollIntoView({behavior:'smooth'})}));
 addEventListener('hashchange',apply);apply();
})();
/* شعارات الشركاء: حركة عند اللمس */
document.querySelectorAll('.logo-box').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.logo-box.tap').forEach(x=>{if(x!==b)x.classList.remove('tap')});b.classList.toggle('tap')}));


